47	
48	  public HoodieFunctionalIndexDefinition() {
49	  }
50	
51	  public HoodieFunctionalIndexDefinition(String indexName, String indexType, String indexFunction, List<String> sourceFields,
52	                                         Map<String, String> indexOptions) {
53	    this.indexName = indexName;
54	    this.indexType = indexType;
55	    this.indexFunction = indexFunction;
56	    this.sourceFields = sourceFields;
57	    this.indexOptions = indexOptions;
58	  }
59	
