62	  }
63	
64	  public List<String> getSourceFields() {
65	    return sourceFields;
66	  }
67	
68	  public Map<String, String> getIndexOptions() {
69	    return indexOptions;
70	  }
71	
72	  public String getIndexName() {
73	    return indexName;
74	  }
75	
76	  public String getIndexType() {
77	    return indexType;
78	  }
79	
80	  @Override
81	  public String toString() {
82	    return "HoodieFunctionalIndexDefinition{"
83	        + "indexName='" + indexName + '\''
