38	/**
39	 * Tests for {@link MetadataPartitionType}.
40	 */
41	public class TestMetadataPartitionType {
42	
43	  @ParameterizedTest
44	  @EnumSource(MetadataPartitionType.class)
45	  public void testPartitionEnabledByConfigOnly(MetadataPartitionType partitionType) {
46	    HoodieTableMetaClient metaClient = Mockito.mock(HoodieTableMetaClient.class);
47	    HoodieTableConfig tableConfig = Mockito.mock(HoodieTableConfig.class);
48	
49	    // Simulate the configuration enabling given partition type, but the meta client not having it available (yet to initialize the partition)
50	    Mockito.when(metaClient.getTableConfig()).thenReturn(tableConfig);
51	    Mockito.when(tableConfig.isMetadataPartitionAvailable(partitionType)).thenReturn(false);
52	    Mockito.when(metaClient.getFunctionalIndexMetadata()).thenReturn(Option.empty());
53	    HoodieMetadataConfig.Builder metadataConfigBuilder = HoodieMetadataConfig.newBuilder();
54	    int expectedEnabledPartitions;
55	    switch (partitionType) {
56	      case FILES:
57	      case FUNCTIONAL_INDEX:
58	        metadataConfigBuilder.enable(true);
59	        expectedEnabledPartitions = 1;
60	        break;
61	      case COLUMN_STATS:
62	        metadataConfigBuilder.enable(true).withMetadataIndexColumnStats(true);
63	        expectedEnabledPartitions = 2;
64	        break;
65	      case BLOOM_FILTERS:
66	        metadataConfigBuilder.enable(true).withMetadataIndexBloomFilter(true);
67	        expectedEnabledPartitions = 2;
68	        break;
69	      case RECORD_INDEX:
70	        metadataConfigBuilder.enable(true).withEnableRecordIndex(true);
71	        expectedEnabledPartitions = 2;
72	        break;
73	      case PARTITION_STATS:
74	        metadataConfigBuilder.enable(true).withMetadataIndexPartitionStats(true).withColumnStatsIndexForColumns("partitionCol");
75	        expectedEnabledPartitions = 2;
76	        break;
77	      default:
78	        throw new IllegalArgumentException("Unknown partition type: " + partitionType);
79	    }
80	
81	    List<MetadataPartitionType> enabledPartitions = MetadataPartitionType.getEnabledPartitions(metadataConfigBuilder.build().getProps(), metaClient);
82	
83	    // Verify partition type is enabled due to config
84	    if (partitionType == MetadataPartitionType.FUNCTIONAL_INDEX) {
85	      assertEquals(1, enabledPartitions.size(), "FUNCTIONAL_INDEX should be enabled by SQL, only FILES is enabled in this case.");
86	      assertTrue(enabledPartitions.contains(MetadataPartitionType.FILES));
87	    } else {
88	      assertEquals(expectedEnabledPartitions, enabledPartitions.size());
89	      assertTrue(enabledPartitions.contains(partitionType));
90	    }
91	  }
92	
93	  @Test
94	  public void testPartitionAvailableByMetaClientOnly() {
95	    HoodieTableMetaClient metaClient = Mockito.mock(HoodieTableMetaClient.class);
96	    HoodieTableConfig tableConfig = Mockito.mock(HoodieTableConfig.class);
97	
98	    // Simulate the meta client having RECORD_INDEX available but config not enabling it
99	    Mockito.when(metaClient.getTableConfig()).thenReturn(tableConfig);
100	    Mockito.when(tableConfig.isMetadataPartitionAvailable(MetadataPartitionType.FILES)).thenReturn(true);
101	    Mockito.when(metaClient.getFunctionalIndexMetadata()).thenReturn(Option.empty());
102	    Mockito.when(metaClient.getTableConfig().isMetadataPartitionAvailable(MetadataPartitionType.RECORD_INDEX)).thenReturn(true);
103	    HoodieMetadataConfig metadataConfig = HoodieMetadataConfig.newBuilder().enable(true).withEnableRecordIndex(false).build();
104	
105	    List<MetadataPartitionType> enabledPartitions = MetadataPartitionType.getEnabledPartitions(metadataConfig.getProps(), metaClient);
106	
107	    // Verify RECORD_INDEX and FILES is enabled due to availability
108	    assertEquals(2, enabledPartitions.size(), "RECORD_INDEX and FILES should be available");
