  /**
   * Returns the {@link MetadataPartitionType} corresponding to the given metadata table partition path.
   * <p>
   * For functional and secondary indexes the partition path only carries the type prefix, hence a
   * {@code startsWith} match is used for those types.
   *
   * @param partitionPath the metadata table partition path.
   * @return the matching {@link MetadataPartitionType}.
   * @throws IllegalArgumentException if the partition path does not map to any known partition type.
   */
  public static MetadataPartitionType fromPartitionPath(String partitionPath) {
    if (partitionPath.equals(HoodieTableMetadataUtil.PARTITION_NAME_FILES)) {
      return FILES;
    } else if (partitionPath.startsWith(HoodieTableMetadataUtil.PARTITION_NAME_FUNCTIONAL_INDEX_PREFIX)) {
      return FUNCTIONAL_INDEX;
    } else if (partitionPath.startsWith(HoodieTableMetadataUtil.PARTITION_NAME_SECONDARY_INDEX_PREFIX)) {
      return SECONDARY_INDEX;
    } else if (partitionPath.equals(HoodieTableMetadataUtil.PARTITION_NAME_COLUMN_STATS)) {
      return COLUMN_STATS;
    } else if (partitionPath.equals(HoodieTableMetadataUtil.PARTITION_NAME_BLOOM_FILTERS)) {
      return BLOOM_FILTERS;
    } else if (partitionPath.equals(HoodieTableMetadataUtil.PARTITION_NAME_RECORD_INDEX)) {
      return RECORD_INDEX;
    } else if (partitionPath.equals(HoodieTableMetadataUtil.PARTITION_NAME_PARTITION_STATS)) {
      return PARTITION_STATS;
    }
    throw new IllegalArgumentException("No MetadataPartitionType for partition path: " + partitionPath);
